<script lang="ts">
 import {onMount} from 'svelte';
 import type {Snippet} from 'svelte';
 import {Editor,Mark} from '@tiptap/core';
 import StarterKit from '@tiptap/starter-kit';
 import Link from '@tiptap/extension-link';
 import Image from '@tiptap/extension-image';
 import {TableKit} from '@tiptap/extension-table';
 import TurndownService from 'turndown';
 // @ts-expect-error upstream package has no declarations
 import {gfm} from 'turndown-plugin-gfm';
 import {renderNewsMarkdown} from '$lib/news-markdown';
 import {photoFileProblem} from '$lib/content-blocks';
 import '$lib/news-cta.css';
 let {value=$bindable(''),facilityId,disabled=false,onBusy=(_v:boolean)=>{},onSave=()=>{},onToolbar}:{value?:string;facilityId:string;disabled?:boolean;onBusy?:(v:boolean)=>void;onSave?:()=>void;onToolbar?:(tools:Snippet|undefined)=>void}=$props();
 let host:HTMLDivElement,file:HTMLInputElement;
 let editor:Editor|undefined=$state.raw(),revision=$state(0),menu=$state(false),panel=$state<'link'|'cta'|'image'|null>(null),label=$state(''),url=$state(''),variant=$state('cta'),uploading=$state(false),problem=$state(''),selected=$state(false),imageSelected=$state(false);
 let savedSelection={from:1,to:1},slashRange:{from:number;to:number}|null=null;
 const locked=$derived(disabled||uploading);
 const commands=[{id:'p',name:'本文',hint:'通常の文章'},{id:'h2',name:'大見出し',hint:'セクションを区切る'},{id:'h3',name:'小見出し',hint:'内容を整理する'},{id:'ul',name:'箇条書き',hint:'項目を並べる'},{id:'ol',name:'番号リスト',hint:'手順を説明する'},{id:'quote',name:'引用',hint:'引用文を表示する'},{id:'image',name:'画像',hint:'写真をアップロード'},{id:'cta',name:'CTAボタン',hint:'予約・お問い合わせへ誘導'},{id:'hr',name:'区切り線',hint:'余白と線で区切る'},{id:'table',name:'表',hint:'3列の表を追加'}];
 const td=new TurndownService({headingStyle:'atx',bulletListMarker:'-',codeBlockStyle:'fenced',emDelimiter:'*'});td.use(gfm);
 td.addRule('newsLink',{filter:'a',replacement:(content,node)=>{const el=node as HTMLAnchorElement,href=el.getAttribute('href')||'';if(!safe(href))return content;const cls=el.getAttribute('class')||'',kind=cls.includes('news-cta--outline')?'cta-outline':cls.includes('news-cta')?'cta':null;return '['+content+']('+href.replace(/\(/g,'%28').replace(/\)/g,'%29')+(kind?' "'+kind+'"':'')+')';}});
 td.addRule('red',{filter:node=>node.nodeName==='SPAN'&&!!(node as HTMLElement).style.color,replacement:content=>'=='+content+'=='});
 const NewsLink=Link.extend({addAttributes(){return {...this.parent?.(),class:{default:null},title:{default:null}};}});
 const Red=Mark.create({name:'red',parseHTML(){return [{tag:'span[style*="color"]'}];},renderHTML(){return ['span',{style:'color:#dc2626;font-weight:600'},0];}});
 function safe(href:string){return /^(https?:\/\/[^\s]+|tel:[^\s]+|mailto:[^\s]+|\/(?!\/)|#)/i.test(href)&&!/["<>\r\n]/.test(href);}
 function sync(){if(!editor)return;value=td.turndown(editor.getHTML());revision++;}
 function selection(){if(!editor)return;selected=!editor.state.selection.empty;imageSelected=editor.isActive('image');savedSelection={from:editor.state.selection.from,to:editor.state.selection.to};revision++;}
 onMount(()=>{let disposed=false;const observer=new IntersectionObserver(entries=>{if(!entries.some(e=>e.isIntersecting)||editor||disposed)return;editor=new Editor({element:host,extensions:[StarterKit.configure({link:false}),NewsLink.configure({openOnClick:false}),Image.configure({allowBase64:false}),TableKit,Red],content:renderNewsMarkdown(value),editable:!locked,editorProps:{attributes:{'aria-label':'お知らせ本文（見たまま編集）',role:'textbox','aria-multiline':'true'},handleKeyDown:(view,event)=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();onSave();return true;}if(event.key==='Escape'){menu=false;panel=null;}if(event.key==='/'&&view.state.selection.empty&&view.state.selection.$from.parent.textContent===''){event.preventDefault();slashRange=null;menu=true;return true;}return false;},handlePaste:(_view,event)=>{const files=Array.from(event.clipboardData?.files??[]).filter(f=>f.type.startsWith('image/'));if(files.length){void upload(files);return true;}return false;},handleDrop:(_view,event,_slice,moved)=>{if(!moved&&event.dataTransfer?.files.length){void upload(Array.from(event.dataTransfer.files));return true;}return false;}},onUpdate:sync,onSelectionUpdate:selection,onTransaction:()=>revision++});observer.disconnect();});observer.observe(host);return()=>{disposed=true;observer.disconnect();editor?.destroy();};});
 onMount(()=>{onToolbar?.(toolbar);return()=>onToolbar?.(undefined);});
 $effect(()=>{editor?.setEditable(!locked,false);});
 function active(mark:string){void revision;return editor?.isActive(mark)??false;}
 function run(id:string){if(!editor||locked)return;menu=false;if(slashRange){editor.chain().focus().deleteRange(slashRange).run();slashRange=null;}const c=editor.chain().focus();if(id==='p')c.setParagraph().run();if(id==='h2')c.toggleHeading({level:2}).run();if(id==='h3')c.toggleHeading({level:3}).run();if(id==='ul')c.toggleBulletList().run();if(id==='ol')c.toggleOrderedList().run();if(id==='quote')c.toggleBlockquote().run();if(id==='hr')c.setHorizontalRule().run();if(id==='table')c.insertTable({rows:3,cols:3,withHeaderRow:true}).run();if(id==='image'||id==='cta')open(id);}
 function open(kind:'link'|'cta'|'image'){if(!editor||locked)return;if(kind!=='image'&&editor.isActive('link'))editor.commands.extendMarkRange('link');selection();menu=false;panel=kind;problem='';const a=editor.getAttributes('link');url=a.href||(facilityId==='f-nishiwaga'&&kind==='cta'?'https://www.yamado.co.jp/reservation/':'https://');label=kind==='image'?editor.getAttributes('image').alt||'':editor.state.doc.textBetween(savedSelection.from,savedSelection.to,' ')||(kind==='cta'?'宿泊プラン・空室を確認':'');variant=a.class?.includes('outline')?'cta-outline':'cta';}
 function apply(){if(!editor||locked||!panel)return;if(panel==='image'){editor.chain().focus().updateAttributes('image',{alt:label}).run();panel=null;return;}if(!safe(url)||!label.trim()){problem='文字と正しいリンク先を入力してください。';return;}const attrs={href:url,class:panel==='cta'?'news-cta'+(variant==='cta-outline'?' news-cta--outline':''):null};editor.chain().focus().setTextSelection(savedSelection).insertContent({type:'text',text:label.trim(),marks:[{type:'link',attrs}]}).run();panel=null;}
 async function upload(files:File[]){if(locked||!editor||!files.length)return;if(files.length>8){problem='一度に追加できる画像は8枚までです。';return;}for(const f of files){const err=photoFileProblem(f);if(err){problem=err;return;}}uploading=true;onBusy(true);problem='';const at=editor.state.selection.from;let cursor=at;try{for(const f of files){const data=new FormData();data.set('file',f);data.set('facilityId',facilityId);const r=await fetch('/admin/news/images',{method:'POST',body:data,signal:AbortSignal.timeout(60000)});const j=await r.json();if(!r.ok)throw Error(j.error||'画像を追加できません。');editor.chain().insertContentAt(cursor,{type:'image',attrs:{src:j.url,alt:label||f.name.replace(/\.[^.]+$/,'')}}).run();cursor=editor.state.selection.to;}}catch(e){problem=e instanceof Error?e.message:'画像を追加できません。';}finally{uploading=false;onBusy(false);panel=null;if(file)file.value='';}}
 function moveImage(delta:number){if(!editor||!imageSelected)return;const {from}=editor.state.selection,node=editor.state.doc.nodeAt(from);if(!node)return;const parent=editor.state.selection.$from.parent,index=editor.state.selection.$from.index();if((delta<0&&index===0)||(delta>0&&index>=parent.childCount-1))return;const target=delta<0?from-parent.child(index-1).nodeSize:from+parent.child(index+1).nodeSize;editor.chain().focus().deleteRange({from,to:from+node.nodeSize}).insertContentAt(target,node.toJSON()).run();}
</script>
{#snippet toolbar()}
<div class="rich-tools">
 <div class="rich-toolbar" role="toolbar" aria-label="本文の編集ツール">
  <button type="button" class="add" disabled={locked} aria-expanded={menu} onclick={()=>{menu=!menu;panel=null;}}>＋ ブロック</button>
  <select aria-label="段落の種類" disabled={locked} onchange={e=>run(e.currentTarget.value)} value={active('heading')?editor?.getAttributes('heading').level===2?'h2':'h3':'p'}><option value="p">本文</option><option value="h2">大見出し</option><option value="h3">小見出し</option><option value="ul">箇条書き</option><option value="ol">番号リスト</option><option value="quote">引用</option></select>
  <button type="button" disabled={locked} class:active={active('bold')} aria-label="太字" onclick={()=>editor?.chain().focus().toggleBold().run()}><b>B</b></button><button type="button" disabled={locked} class:active={active('italic')} aria-label="斜体" onclick={()=>editor?.chain().focus().toggleItalic().run()}><i>I</i></button>
  <button type="button" disabled={locked} onclick={()=>open('link')}>リンク</button><button type="button" disabled={locked} onclick={()=>open('image')}>画像</button><button type="button" disabled={locked} onclick={()=>open('cta')}>CTAボタン</button>
  <span class="spacer"></span><button type="button" aria-label="元に戻す" disabled={locked} onclick={()=>editor?.chain().focus().undo().run()}>↶</button><button type="button" aria-label="やり直す" disabled={locked} onclick={()=>editor?.chain().focus().redo().run()}>↷</button>
 </div>
 {#if selected&&!imageSelected&&!panel}<div class="context-bar"><span>選択した文字</span><button type="button" disabled={locked} onclick={()=>editor?.chain().focus().toggleBold().run()}>太字</button><button type="button" disabled={locked} onclick={()=>open('link')}>リンクを編集</button><button type="button" disabled={locked} onclick={()=>open('cta')}>CTAにする</button></div>{/if}
 {#if imageSelected&&!panel}<div class="context-bar"><span>選択した画像</span><button type="button" disabled={locked} onclick={()=>open('image')}>説明を編集</button><button type="button" disabled={locked} onclick={()=>moveImage(-1)}>↑ 上へ</button><button type="button" disabled={locked} onclick={()=>moveImage(1)}>↓ 下へ</button><button type="button" disabled={locked} onclick={()=>editor?.chain().focus().deleteSelection().run()}>本文から外す</button></div>{/if}
 {#if menu}<div class="block-menu" role="menu" aria-label="ブロックを追加">{#each commands as cmd}<button type="button" role="menuitem" onclick={()=>run(cmd.id)}><strong>{cmd.name}</strong><span>{cmd.hint}</span></button>{/each}<button type="button" onclick={()=>menu=false}>閉じる</button></div>{/if}
 {#if panel}<div class="edit-panel"><strong>{panel==='image'?'画像':panel==='cta'?'CTAボタン':'リンク'}</strong><label>{panel==='image'?'画像の説明':'表示する文字'}<input bind:value={label} maxlength="200" disabled={locked}/></label>{#if panel!=='image'}<label>リンク先<input bind:value={url} placeholder="https://" disabled={locked}/></label>{#if panel==='cta'}<label>デザイン<select bind:value={variant}><option value="cta">塗りつぶし</option><option value="cta-outline">枠線</option></select></label>{/if}<button type="button" disabled={locked} onclick={apply}>反映</button>{:else}{#if imageSelected}<button type="button" disabled={locked} onclick={apply}>説明を保存</button>{/if}<button type="button" disabled={locked} onclick={()=>file.click()}>画像をアップロード</button>{/if}<button type="button" onclick={()=>panel=null}>閉じる</button></div>{/if}
</div>
{/snippet}
<div class="rich-editor" data-revision={revision}>
 {#if !onToolbar}{@render toolbar()}{/if}
 <input bind:this={file} type="file" accept="image/png,image/jpeg,image/webp,image/avif" multiple class="file" tabindex="-1" aria-label="本文に追加する画像" onchange={e=>void upload(Array.from(e.currentTarget.files??[]))}/>
 <div class="document-scroll"><div class="document" bind:this={host}></div></div>
 <div class="rich-status"><span>{uploading?'画像をアップロード中…':'空の行で / を入力するとブロックを追加できます'}</span><span>{value.length.toLocaleString()}文字</span></div>
 {#if problem}<p class="error" role="alert">{problem}</p>{/if}
</div>
<style>
.rich-editor{position:relative;background:#fff;color:#333}.rich-tools{position:relative}.rich-toolbar{justify-content:flex-end;display:flex;gap:4px;align-items:center;flex-wrap:wrap;background:#fff;padding:6px 8px}.rich-toolbar button,.rich-toolbar select{padding:6px 10px;border-radius:5px;font-size:13px;min-height:34px}.rich-toolbar button:hover,.context-bar button:hover{background:#f0f2ed}.rich-toolbar .active{background:#eaf0e3}.rich-toolbar .add{background:#f2f4ef}.spacer{width:1px;height:20px;background:#e5e8e0;margin:0 4px}.document-scroll{min-height:340px;overflow:visible}.document{width:100%;padding:0 0 72px}.document :global(.tiptap){min-height:300px;outline:none;font-size:16px;line-height:2;color:#30362d;overflow-wrap:anywhere}.document :global(p){margin:0 0 1em}.document :global(h2){font-size:25px;font-weight:650;line-height:1.6;margin:1.8em 0 .7em}.document :global(h3){font-size:20px;font-weight:600;margin:1.5em 0 .7em}.document :global(img){display:block;max-width:100%;height:auto;border-radius:6px;margin:24px 0;cursor:pointer}.document :global(.ProseMirror-selectednode){outline:3px solid #849b6c;outline-offset:5px}.document :global(a){color:#79673f;text-decoration:underline;cursor:text}.document :global(ul){list-style:disc;padding-left:1.5em}.document :global(ol){list-style:decimal;padding-left:1.5em}.document :global(blockquote){border-left:3px solid #ccc;padding-left:1.2em;color:#666}.document :global(table){border-collapse:collapse;width:100%;margin:20px 0}.document :global(th),.document :global(td){border:1px solid #ddd;padding:8px;min-width:60px}.document :global(hr){border:0;border-top:1px solid #ddd;margin:32px 0}.document :global(pre){background:#f5f5f5;padding:16px;white-space:pre-wrap}.rich-status{display:flex;justify-content:space-between;gap:10px;padding:10px 18px;color:#929787;font-size:11px;border-top:1px solid #eee}.context-bar{display:flex;align-items:center;flex-wrap:wrap;gap:8px;padding:8px 18px;background:#f5f7f1;font-size:12px}.context-bar span{color:#89917f}.context-bar button{padding:4px 8px;border-radius:4px}.block-menu{position:absolute;z-index:8;top:52px;left:16px;max-height:50vh;width:280px;overflow:auto;background:#fff;box-shadow:0 8px 36px #0002;border:1px solid #e6e8e1;border-radius:9px;padding:8px}.block-menu button{display:flex;flex-direction:column;gap:2px;width:100%;padding:10px 12px;text-align:left;border-radius:5px}.block-menu button:hover{background:#f0f3eb}.block-menu strong{font-size:14px;font-weight:500}.block-menu span{font-size:11px;color:#999}.edit-panel{display:flex;gap:10px;align-items:end;flex-wrap:wrap;background:#f6f7f3;padding:16px;border-bottom:1px solid #e2e5dc;font-size:12px}.edit-panel strong{width:100%}.edit-panel label{display:grid;gap:5px;flex:1;min-width:160px}.edit-panel input,.edit-panel select{padding:8px;border:1px solid #dce0d4;border-radius:5px;background:#fff}.edit-panel button{padding:8px 12px;background:#fff;border:1px solid #dce0d4;border-radius:5px}.file{position:absolute;opacity:0;pointer-events:none;width:1px;height:1px}.error{color:#a65c3c;background:#fff3ec;padding:12px;font-size:13px}button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid #8fa17e;outline-offset:2px}button:disabled{opacity:.4}@media(max-width:700px){.document{padding:0 0 48px}.document :global(.tiptap){font-size:15px}.rich-toolbar{padding:8px;gap:0}.rich-toolbar button{font-size:12px;padding:6px 8px}.rich-status{font-size:11px}.document-scroll{height:auto}}
</style>
